/**
 * Reads the SEVERITY line the report writer ends with.
 * Inputs: input.report (the swarm's final text), input.threshold (review threshold).
 * Returns { severity, needsReview } for review_gate.
 */
const match = /SEVERITY:\s*(\d+(?:\.\d+)?)/i.exec(String(input.report || ''));
const severity = match ? Math.min(10, Math.max(0, Number(match[1]))) : 10; // unreadable: review it
const threshold = Number(input.threshold ?? 7);
return { severity, needsReview: severity >= threshold };
